-- Croatia Explorer — reference data seed.
-- Run in the Supabase SQL editor AFTER schema.sql. Idempotent (ON CONFLICT (id) DO NOTHING).
-- Counts: 9 types, 21 counties, 63 cities, 204 default POIs.

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

-- Finalize the poi_progress → pois foreign key now that pois is populated:
-- drop any saved progress that points at a POI no longer in the data, then validate the
-- constraint (added NOT VALID in schema.sql). Safe to re-run.
delete from public.poi_progress
  where poi_id not in (select id from public.pois);
alter table public.poi_progress validate constraint poi_progress_poi_id_fkey;
